INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(8001, '2 Samuel 19:7', '2 Samuel', 19, 7, '&nbsp;اوس لاړ شه او د خپلو سړو حوصله افزائى وکړه خو کۀ تا داسې ونۀ کړل نو زۀ د مالِک خُدائ په نوم قسم خورم چې تر سبا سحر پورې به د هغوئ يو کس هم تا سره نۀ وى. دا به دومره لوئ مصيبت وى چې په ټول ژوند کښې به داسې مصيبت درباندې نۀ وى تېر شوے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8002, '2 Samuel 19:8', '2 Samuel', 19, 8, '&nbsp;نو بادشاه پاڅېدو، لاړو او د ښار د دروازې سره نزدې کښېناستو. د هغۀ سړى خبر شول چې هغه هلته دے او ټول ترې نه ګېرچاپېره راټول شول. د حضرت داؤد يروشلم ته واپس روانېدل په دې دوران کښې ټول بنى اِسرائيليان خپلو کورونو ته تښتېدلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8003, '2 Samuel 19:9', '2 Samuel', 19, 9, '&nbsp;په ټول مُلک کښې هغوئ په خپلو کښې په لانجه شول. هغوئ يو بل ته ووئيل، ”داؤد بادشاه مونږ د خپلو دشمنانو نه بچ کړُو. هغۀ مونږ د فلستيانو نه بچ کړُو، خو هغه اوس د ابى‌سلوم نه وتښتېدو او مُلک يې پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8004, '2 Samuel 19:10', '2 Samuel', 19, 10, '&nbsp;مونږ ابى‌سلوم خپل بادشاه مقرر کړو، خو هغه په جنګ کښې وژلے شوے دے. نو څوک داؤد بادشاه واپس ولې نۀ راولى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8005, '2 Samuel 19:11', '2 Samuel', 19, 11, '&nbsp;بنى اِسرائيلو چې څۀ وئيل نو هغه خبر داؤد بادشاه ته ورسېدو. نو هغۀ صدوق او ابياتار اِمامان ولېږل چې د يهوداه د مشرانو نه تپوس وکړى، ”تاسو دې ولې هغه آخرى قبيله يئ چې د داؤد بادشاه محل ته د واپس راوستلو خيال لرئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8006, '2 Samuel 19:12', '2 Samuel', 19, 12, '&nbsp;تاسو زما خپلوان يئ او زما خپله وينه يئ، تاسو دې ولې هغه آخرى قبيله يئ چې ما واپس بوځئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8007, '2 Samuel 19:13', '2 Samuel', 19, 13, '&nbsp;داؤد هغوئ ته دا هم وفرمائيل چې عماسا ته ووائى، ”تۀ زما رشته‌دار يې. د نن نه زۀ تا د يوآب په ځائ د لښکر مشر مقرروم. خو کۀ ما داسې ونۀ کړل نو خُدائ پاک دې ما هلاک کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8008, '2 Samuel 19:14', '2 Samuel', 19, 14, '&nbsp;د داؤد په خبرو باندې د يهوداه ټول سړى د هغۀ ملګرى شول او هغوئ هغۀ له خبر ولېږلو چې د خپلو ټولو آفسرانو سره واپس راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8009, '2 Samuel 19:15', '2 Samuel', 19, 15, '&nbsp;نو بادشاه راواپس شو او د اُردن سيند ته ورسېدو. نو د يهوداه خلق جِلجال ته راغلى وُو چې د بادشاه سره مِلاو شى او د اُردن سيند نه يې پورې باسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8010, '2 Samuel 19:16', '2 Samuel', 19, 16, '&nbsp;هم په هغه وخت د بحوريم د علاقې د جيرا زوئ سِمعى بنيامينے د اُردن سيند له تېز لاړو چې د داؤد بادشاه سره مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8011, '2 Samuel 19:17', '2 Samuel', 19, 17, '&nbsp;د هغۀ سره د بنيامين د قبيلې زر سړى وُو. او د ساؤل د خاندان نوکر ضيبا هم د خپلو پينځلسو زامنو او شلو نوکرانو سره راغلو او هغوئ د بادشاه نه مخکښې د اُردن سيند نه پورې وتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8012, '2 Samuel 19:18', '2 Samuel', 19, 18, '&nbsp;هغوئ په ګودر د سيند نه پورې وتل چې د شاهى خاندان په پورې وتلو کښې مدد وکړى او چې هغه څۀ وکړى څۀ چې بادشاه غوښتل. د حضرت داؤد په سِمعى باندې ترس کول کله چې بادشاه د سيند نه پورې وتو، نو د جيرا زوئ سِمعى د هغۀ په مخکښې پړمخې پرېوتو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8013, '2 Samuel 19:19', '2 Samuel', 19, 19, '&nbsp;او وې وئيل، ”بادشاه سلامت، زما هغه غلطى معاف کړه چې په کومه ورځ تۀ د يروشلم نه تلې او ما کړې وه. او هغه د زړۀ نه وباسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8014, '2 Samuel 19:20', '2 Samuel', 19, 20, '&nbsp;صاحِبه، ما ته پته ده چې ما ګناه کړې ده، نو دا ځکه زۀ د شمالى قبيلو نه وړومبے کس يم چې نن تا سره بادشاه سلامت مِلاوېدو له راغلے يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8015, '2 Samuel 19:21', '2 Samuel', 19, 21, '&nbsp;د ضروياه زوئ ابيشى وئيل، ”سِمعى دې ووژلے شى ځکه چې هغۀ هغه چا ته کنځل کړى دى څوک چې مالِک خُدائ خوښ کړے دے چې بادشاه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8016, '2 Samuel 19:22', '2 Samuel', 19, 22, '&nbsp;خو داؤد ابيشى او د هغۀ ورور يوآب ته وفرمائيل، ”ستاسو نه چا مشوره غوښتې ده؟ تاسو نن زما دشمنان شوى يئ؟ زۀ اوس هغه څوک يم چې د بنى اِسرائيلو بادشاه يم او نن به يو بنى اِسرائيلے هم نۀ شى وژلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8017, '2 Samuel 19:23', '2 Samuel', 19, 23, '&nbsp;او هغۀ سِمعى ته وفرمائيل، ”زۀ تا سره وعده کوم چې تۀ به نۀ شې وژلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8018, '2 Samuel 19:24', '2 Samuel', 19, 24, '&nbsp;بيا د ساؤل نمسے مفيبوست راغلو چې د بادشاه سره مِلاو شى. د هغه وخت نه واخله چې بادشاه د يروشلم نه تلے وو تر هغې پورې چې هغه کامياب راواپس شو مفيبوست نۀ خپلې پښې وينځلې وې، نۀ يې خپله ږيره سمه کړې وه او نۀ يې خپلې جامې وينځلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8019, '2 Samuel 19:25', '2 Samuel', 19, 25, '&nbsp;کله چې مفيبوست د يروشلم نه راورسېدو چې د بادشاه سره مِلاو شى، نو بادشاه هغۀ ته وفرمائيل، ”مفيبوسته، تۀ ما سره ولې نۀ وې تلے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8020, '2 Samuel 19:26', '2 Samuel', 19, 26, '&nbsp;هغۀ ورته ووئيل، ”بادشاه سلامت، لکه څنګه چې تا ته پته ده چې زۀ ګوډ يم. ما خپل نوکر ته ووئيل چې زما خر کته کړى نو چې زۀ تا سره لاړ شم، خو هغۀ ما سره دوکه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8021, '2 Samuel 19:27', '2 Samuel', 19, 27, '&nbsp;بادشاه سلامت، هغۀ زما په حقله تا ته دروغ وئيلى دى، خو تۀ د خُدائ پاک د فرښتې په شان يې او چې تا ته څۀ ټيک ښکارى نو هغه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8022, '2 Samuel 19:28', '2 Samuel', 19, 28, '&nbsp;بادشاه سلامت، زما د پلار مکمل خاندان د دې حقداره ده چې ووژلے شى، خو تا زۀ د دې حقدار کړم چې ستا د دسترخوان روټۍ وخورم. بادشاه سلامت، زۀ هيڅ حق نۀ لرم چې تا ته د رحم فرياد وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8023, '2 Samuel 19:29', '2 Samuel', 19, 29, '&nbsp;بادشاه ورته وفرمائيل، ”تۀ به نور هيڅ نۀ وائې. ما دا فېصله کړې ده چې تۀ او ضيبا به د ساؤل جائيداد په خپلو کښې تقسيم کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8024, '2 Samuel 19:30', '2 Samuel', 19, 30, '&nbsp;مفيبوست ورته ووئيل، ”پرېږده چې دا ټول د ضيبا شى. بادشاه سلامت، زما دپاره دا کافى ده چې تۀ په خېر سره کور ته راغلے يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8025, '2 Samuel 19:31', '2 Samuel', 19, 31, '&nbsp;د جِلعاد برزلى هم د راجليم نه راغلے وو چې د بادشاه د اُردن سيند نه پورې وتو کښې ملګرتيا وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8026, '2 Samuel 19:32', '2 Samuel', 19, 32, '&nbsp;برزلى ډېر بوډا سړے وو چې د اتياو کالو وو. هغه ډېر مالداره وو او کله چې بادشاه په محنايم کښې اوسېدو نو برزلى به خوراک ورلېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8027, '2 Samuel 19:33', '2 Samuel', 19, 33, '&nbsp;بادشاه هغۀ ته وفرمائيل، ”ما سره يروشلم ته لاړ شه، چې کله تۀ ما سره يې نو زۀ به ستا خيال ساتم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8028, '2 Samuel 19:34', '2 Samuel', 19, 34, '&nbsp;خو برزلى ورته ووئيل، ”بادشاه سلامت، زۀ به نور څومره ژوندے يم، چې زۀ تا سره يروشلم ته لاړ شم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8029, '2 Samuel 19:35', '2 Samuel', 19, 35, '&nbsp;زۀ د اتياو کالو يم، او يو څيز هم ما له مزه نۀ راکوى. زۀ چې خوراک څښاک کوم نو د هغې په خوند نۀ پوهېږم او زۀ د سندرغاړو آوازونه نۀ اورم. بادشاه سلامت، زۀ به تاسو باندې صِرف بوج يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8030, '2 Samuel 19:36', '2 Samuel', 19, 36, '&nbsp;زۀ د داسې يو لوئ اِنعام حقدار نۀ يم، خو زۀ به د اُردن نه اخوا لږ غوندې تا سره لاړ شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8031, '2 Samuel 19:37', '2 Samuel', 19, 37, '&nbsp;بيا به زۀ واپس کور ته راشم چې په خپل ښار کښې د خپل مور پلار د اديرې سره نزدې مړ شم. زما زوئ کِمهام دا دے حاضر دے، دے به ستا خِدمت کوى، هغه ځان سره بوځه، بادشاه سلامت. د هغۀ دپاره هغه څۀ کوه چې تا ته ښۀ ښکارى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8032, '2 Samuel 19:38', '2 Samuel', 19, 38, '&nbsp;بادشاه ورته وفرمائيل، ”زۀ به هغه ځان سره بوځم او چې تۀ څۀ غواړې نو زۀ به يې د هغۀ دپاره وکړم. او ستا دپاره به هغه څۀ وکړم چې تۀ څۀ غواړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8033, '2 Samuel 19:39', '2 Samuel', 19, 39, '&nbsp;بيا داؤد او د هغۀ ټول سړى د اُردن سيند نه پورې وتل. هغۀ برزلى ښُکل کړو او د هغۀ دپاره يې خپل برکت وغوښتلو او برزلى واپس کور ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8034, '2 Samuel 19:40', '2 Samuel', 19, 40, '&nbsp;کله چې بادشاه پورې وتلو او د يهوداه ټول فوجيان او د اِسرائيل نيم فوجيان ورسره ملګرى وُو، نو هغه جِلجال ته لاړو او کِمهام هم ورسره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8035, '2 Samuel 19:41', '2 Samuel', 19, 41, '&nbsp;بيا ټول اِسرائيليان بادشاه له لاړل او هغۀ ته يې ووئيل، ”بادشاه سلامت، زمونږ وروڼه يعنې د يهوداه سړى دا خيال ولې کوى چې هغوئ دا حق لرلو چې تا بوځى او چې ستا، ستا د خاندان او ستا د سړو د اُردن نه پورې وتو کښې ملګرتيا وکړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8036, '2 Samuel 19:42', '2 Samuel', 19, 42, '&nbsp;د يهوداه سړو ورته ووئيل، ”دا مونږ ځکه وکړل چې بادشاه زمونږ خپلوان دے. نو په دې باندې تاسو ولې غصه يئ؟ مونږ د هغۀ په پېسو نۀ خوراک کړے دے او نۀ هغۀ مونږ له څۀ راکړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8037, '2 Samuel 19:43', '2 Samuel', 19, 43, '&nbsp;د اِسرائيل خلقو ورته ووئيل، ”تاسو چې څومره دعوىٰ کوئ نو مونږ د هغې يو په لس دعوىٰ کوُو چې داؤد زمونږ نه دے، اګر کۀ هغه ستاسو د نسل نه هم وى. تاسو مونږ ته ولې سپک ګورئ؟ تاسو دا مۀ هېروئ چې مونږ هغه وړومبى خلق وُو چې د بادشاه واپس راوستلو خبره مو کړې وه.“ خو د يهوداه سړى د اِسرائيل د سړو نه په خپلو دعوو کولو کښې ډېر سخت وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8038, '2 Samuel 20:1', '2 Samuel', 20, 1, '&nbsp;په جِلجال کښې داسې وشول چې د بنيامين د قبيلې يو بدمعاش سړے وو. هغه د بِکرى زوئ وو او نوم يې شيبا وو. هغۀ بيګل وغږولو او چغه يې کړه، ”نۀ به د داؤد نه په ميراث کښې مونږ ته څۀ مِلاو شى او نۀ مونږ ته د هغۀ نه د مِلاوېدو څۀ اُميد شته. اے بنى اِسرائيلو راځئ چې خپلو کورونو ته ځُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8039, '2 Samuel 20:2', '2 Samuel', 20, 2, '&nbsp;نو داسې اِسرائيليانو د داؤد خِلاف بغاوت وکړو او د شيبا سره روان شول، خو د يهوداه سړى وفادار وُو او د اُردن نه تر يروشلم پورې په داؤد پسې لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8040, '2 Samuel 20:3', '2 Samuel', 20, 3, '&nbsp;کله چې داؤد په يروشلم کښې خپل محل ته ورسېدو، هغۀ هغه لس وېنځې بوتلې چې کومې يې د محل د خيال ساتلو دپاره پرېښې وې او په حِفاظت کښې يې ساتلې وې. هغوئ له يې د ضرورت څيزونه ورکول، خو د هغوئ سره يې څملاستل نۀ کول. په هغوئ باندې ټول عُمر دا پابندى وه چې د کونډو په شان ژوند تېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8041, '2 Samuel 20:4', '2 Samuel', 20, 4, '&nbsp;بادشاه عماسا ته وفرمائيل، ”د يهوداه سړى راغونډ کړه او سبا نه بل سبا د هغوئ سره حاضر شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8042, '2 Samuel 20:5', '2 Samuel', 20, 5, '&nbsp;عماسا د هغوئ د راغونډولو دپاره لاړو، خو چې بادشاه کوم وخت مقرر کړے وو نو هغه هغې له واپس رانۀ غلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8043, '2 Samuel 20:6', '2 Samuel', 20, 6, '&nbsp;نو بادشاه ابيشى ته وفرمائيل، ”شيبا به مونږ له د ابى‌سلوم نه زيات مصيبت جوړوى. زما سړى بوځه او په هغۀ پسې لاړ شه، ګنې کېدے شى چې هغه د پَخو دېوالونو والا ښارونه ونيسى او زمونږ نه وتښتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8044, '2 Samuel 20:7', '2 Samuel', 20, 7, '&nbsp;نو د يوآب سړى او محافظان د ابيشى سره د يروشلم نه روان شول چې په شيبا پسې لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8045, '2 Samuel 20:8', '2 Samuel', 20, 8, '&nbsp;چې کله هغوئ په جبعون کښې لوئ ګټ ته ورسېدل نو عماسا ورسره مِلاو شو. يوآب د جنګ دپاره زغره اغوستې وه، تُوره يې په کاش کښې اېښې وه چې په کمربند پورې يې تړلې وه. چې وړاندې راغلو، نو تُوره وغورزېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8046, '2 Samuel 20:9', '2 Samuel', 20, 9, '&nbsp;يوآب عماسا ته ووئيل، ”زما ملګريه څنګه يې؟“ او د چل دپاره يې خپل ښے لاس د هغۀ ږيرې له وروړلو چې ښُکل يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8047, '2 Samuel 20:10', '2 Samuel', 20, 10, '&nbsp;چې کومه تُوره د يوآب په بل لاس کښې وه نو هغې ته د عماسا خيال نۀ وو او يوآب هغه ورباندې په خېټه ووهلو او کولمې ترې نه بهر په زمکه وغورزېدې، هغه په ټکى مړ شو او يوآب ته د هغۀ د بيا وهلو ضرورت پېښ نۀ شو. بيا يوآب او د هغۀ ورور ابيشے په شيبا پسې روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8048, '2 Samuel 20:11', '2 Samuel', 20, 11, '&nbsp;د يوآب يو سړے د عماسا د لاش سره ودرېدو او آواز يې وکړو، ”څوک چې د يوآب او داؤد ملګرتيا کوى نو هغوئ دې په يوآب پسې روان شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8049, '2 Samuel 20:12', '2 Samuel', 20, 12, '&nbsp;د عماسا لاش په وينو کښې لت پت وو او د سړک په مينځ کښې پروت وو. د يوآب سړى دا وليدل چې هر يو کس ورته د تماشې دپاره ودريږى، نو هغۀ لاش د سړک نه پټى ته راښکلو او څادر يې ورباندې واچولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8050, '2 Samuel 20:13', '2 Samuel', 20, 13, '&nbsp;کله چې هغه لاش د سړک نه لرې کړے شو، نو هر يو کس د يوآب سره په شيبا پسې روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8051, '2 Samuel 20:14', '2 Samuel', 20, 14, '&nbsp;شيبا د بنى اِسرائيلو د ټولو قبيلو د علاقې نه تېر شو او د ابيل‌بيت‌معکه ښار ته راغلو او د بِکرى د قبيلې کسان راغونډ شول او په هغۀ پسې ښار ته ننوتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8052, '2 Samuel 20:15', '2 Samuel', 20, 15, '&nbsp;د يوآب سړى خبر شول چې شيبا هلته دے، نو هغوئ لاړل او ښار يې محاصره کړو. هغوئ بهرنى دېوالونو ته د خاورو ډېرى جوړ کړل او دېوال کنستل يې هم شروع کړل چې دا راوغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8053, '2 Samuel 20:16', '2 Samuel', 20, 16, '&nbsp;هلته په ښار کښې يوه هوښياره ښځه وه چې هغې د دېوال نه چغه کړه، ”اے خلقو واورئ. يوآب ته ووايئ چې دلته راشى، زۀ د هغۀ سره خبرې کول غواړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8054, '2 Samuel 20:17', '2 Samuel', 20, 17, '&nbsp;نو يوآب لاړو او هغې ترې نه تپوس وکړو، ”تۀ يوآب يې څۀ؟“ هغۀ ورته ووئيل، ”آو، زۀ يوآب يم.“ هغې ورته ووئيل، ”صاحِبه، زما خبره واوره.“ هغۀ ورته ووئيل، ”زۀ اورم وايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8055, '2 Samuel 20:18', '2 Samuel', 20, 18, '&nbsp;هغې ورته ووئيل چې، ”په خوا به خلقو وئيل، لاړ شه او د ابيل په ښار کښې به درته د مسئلې حل مِلاو شى، نو چې هغوئ به لاړل نو مسئله به حل شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8056, '2 Samuel 20:19', '2 Samuel', 20, 19, '&nbsp;زمونږ يو عظيم ښار دے، چې په بنى اِسرائيل کښې ډېر د وفا او امن نه ډک دے. دا تۀ ولې تباه کوې؟ تۀ هغه څۀ ورانول غواړې څۀ چې د مالِک خُدائ دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8057, '2 Samuel 20:20', '2 Samuel', 20, 20, '&nbsp;يوآب ورته ووئيل، ”هيچرې نه. زۀ به ستاسو ښار هيڅکله تباه او وران نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8058, '2 Samuel 20:21', '2 Samuel', 20, 21, '&nbsp;زمونږ منصوبه دا نۀ ده. د يو سړى نوم شيبا دے چې هغه د بِکرى زوئ دے، هغه د غرونو د مُلک د اِفرائيم دے، هغۀ د داؤد بادشاه خِلاف بغاوت شروع کړے دے. بس دا يو سړے ما له په لاس کښې راکړه، نو زۀ به د ښار نه ووځم.“ هغې ورته ووئيل، ”مونږ به د هغۀ سر تا ته د دېوال نه دروغورزوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8059, '2 Samuel 20:22', '2 Samuel', 20, 22, '&nbsp;بيا هغه د خپلې منصوبې سره د ښار خلقو له لاړه، هغوئ د شيبا سر پرې کړو او يوآب ته يې د دېوال نه وروغورزولو. هغۀ د دې دپاره بيګل وغږولو چې د هغۀ سړى د ښار نه لاړ شى، نو هغوئ واپس کورونو ته لاړل. او يوآب واپس بادشاه له يروشلم ته راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8060, '2 Samuel 20:23', '2 Samuel', 20, 23, '&nbsp;يوآب د اِسرائيلو د لښکر مشر وو، د يهويدع زوئ بناياه د داؤد د محافظانو مشر وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8061, '2 Samuel 20:24', '2 Samuel', 20, 24, '&nbsp;ادورام د هغه مزدورانو مشر وو چې په زور کار ترې نه اخستے شو، د اخيلود زوئ يهوسفط منشى وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8062, '2 Samuel 20:25', '2 Samuel', 20, 25, '&nbsp;سِوا د دربار منشى وو، صدوق او ابياتار اِمامان وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8063, '2 Samuel 20:26', '2 Samuel', 20, 26, '&nbsp;او د يائير د ښار عيرا هم د داؤد يو اِمام وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8064, '2 Samuel 21:1', '2 Samuel', 21, 1, '&nbsp;د داؤد په بادشاهۍ کښې درې کاله ډېر سخت قحط وو. نو داؤد د مالِک خُدائ سره د دې په حقله خبره وکړه او مالِک خُدائ وفرمائيل، ”ساؤل او د هغۀ خاندان خُون کړے دے، ځکه چې هغۀ د جبعون قبيلې خلق ووژل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8065, '2 Samuel 21:2', '2 Samuel', 21, 2, '&nbsp;(د جبعون خلق اِسرائيليان نۀ وُو، هغوئ د اموريانو ژوندۍ پاتې شوې يوه وړه ډله وه او اِسرائيلو دا لوظ کړے وو چې هغوئ به ژوندى پرېږدى خو ساؤل د يهوداه او د اِسرائيل د قوم پرستۍ په وجه غوښتل چې اموريان تباه کړى.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8066, '2 Samuel 21:3', '2 Samuel', 21, 3, '&nbsp;نو داؤد د جبعون خلق راوغوښتل او هغوئ ته يې ووئيل، ”زۀ ستاسو دپاره څۀ وکړم؟ تاسو سره چې کومه غلطى شوې وه نو زۀ د هغې تاوان درکول غواړم، نو چې تاسو د مالِک خُدائ د خلقو دپاره برکت وغواړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8067, '2 Samuel 21:4', '2 Samuel', 21, 4, '&nbsp;هغوئ جواب ورکړو، ”د ساؤل او د هغۀ د خاندان سره زمونږ لانجه په سپينو او سرو زرو باندې نۀ حل کيږى او نۀ مونږ ته دا حق چې يو اِسرائيلے ووژنو.“ داؤد ترې نه تپوس وکړو، ”نو بيا ستاسو څۀ خيال دے چې ستاسو دپاره څۀ وکړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8068, '2 Samuel 21:5', '2 Samuel', 21, 5, '&nbsp;هغوئ ورته ووئيل، ”ساؤل زمونږ داسې تباه کول غوښتل چې د اِسرائيل په مُلک کښې زمونږ يو کس هم ژوندے پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8069, '2 Samuel 21:6', '2 Samuel', 21, 6, '&nbsp;نو د هغۀ د اولاد نه اووۀ نران مونږ ته حواله کړه او مونږ به يې په جبعه کښې د مالِک خُدائ په وړاندې ووژنو او ځوړند به يې کړُو، چې هغه د مالِک خُدائ د خوښ کړے شوى بادشاه، ساؤل ښار دے.“ نو بادشاه ورته وفرمائيل، ”زۀ به هغوئ تاسو ته حواله کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8070, '2 Samuel 21:7', '2 Samuel', 21, 7, '&nbsp;خو د مالِک خُدائ په نوم د هغه قسم په وجه چې هغۀ او يونتن د يو بل سره کړے وو، داؤد مفيبوست ژوندے پرېښودو، مفيبوست د ساؤل نمسے او د يونتن زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8071, '2 Samuel 21:8', '2 Samuel', 21, 8, '&nbsp;خو هغۀ ارمونى او مفيبوست بوتلل، د ساؤل دا دوه زامن چې د آيه د لور رِصفخ نه پېدا شوى وُو، هغۀ د ساؤل د لور ميرب پينځۀ زامن هم بوتلل، چې د برزلى د زوئ ادرعى نه يې پېدا شوى وُو، چې هغه د محوله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8072, '2 Samuel 21:9', '2 Samuel', 21, 9, '&nbsp;داؤد هغوئ د جبعون خلقو ته حواله کړل، چې د مالِک خُدائ په مخکښې يې په غرۀ باندې قتل کړل، نو ټول اووۀ واړه په يو ځائ مړۀ شول. سپرلے په ختمېدو وو او د اوربشو لَو شروع وو، چې هغوئ ووژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8073, '2 Samuel 21:10', '2 Samuel', 21, 10, '&nbsp;بيا د ساؤل بله ښځه د آيه لور رِصفخ د ټاټ کپړه واخستله چې د ځان دپاره په هغه ګټ باندې څپر جوړ کړى چرته چې مړى پراتۀ وُو او د لَو د شروع کېدو نه واخله د خزان بارانونو د شروع کېدو پورې هغه هلته ايساره شوه. د ورځې به هغې د مړو نه مارغان شړل او د شپې به يې دا د ځنګلى ځناورو نه بچ کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8074, '2 Samuel 21:11', '2 Samuel', 21, 11, '&nbsp;چې داؤد خبر شو چې رِصفخ څۀ کړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8075, '2 Samuel 21:12', '2 Samuel', 21, 12, '&nbsp;نو هغه لاړو او په جِلعاد کښې يې د يبيس د خلقو نه د ساؤل او د هغۀ د زوئ يونتن هډُوکى واخستل. (هغوئ دا په بيت‌شان کښې د بازار نه پټ کړى وُو، چرته چې فلستيانو لاشونه راځوړند کړى وُو. دا په هغه وخت وُو چې په کومه ورځ هغوئ د جِلبوعه په غرۀ باندې ساؤل وژلے وو.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8076, '2 Samuel 21:13', '2 Samuel', 21, 13, '&nbsp;داؤد د ساؤل او يونتن او د هغه اوو سړو هډُوکى هم يوړل چې کوم ځوړند کړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8077, '2 Samuel 21:14', '2 Samuel', 21, 14, '&nbsp;بيا هغوئ د بنيامين په علاقه ضِلع کښې د ساؤل پلار قيس په قبر کښې د ساؤل او د يونتن هډُوکى ښخ کړل، هم هغه شان چې څنګه بادشاه حُکم کړے وو. او د هغې نه پس خُدائ پاک د هغوئ د مُلک دپاره سوال قبول کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8078, '2 Samuel 21:15', '2 Samuel', 21, 15, '&nbsp;د فلستيانو او د اِسرائيل په مينځ کښې يو بل جنګ وشو او داؤد او د هغۀ سړى لاړل او فلستيانو سره يې جنګ وکړو. په يو جنګ کښې داؤد ستړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8079, '2 Samuel 21:16', '2 Samuel', 21, 16, '&nbsp;د دېوانو د نسل اشبى‌بنوب د زېړو يوه نېزه روانه کړې وه چې تقريباً درې نيم کلو وزن يې وو او يوه نوې تُوره هم ورسره وه، د هغۀ اراده دا وه چې داؤد ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8080, '2 Samuel 21:17', '2 Samuel', 21, 17, '&nbsp;خو د ضروياه زوئ ابيشے د داؤد د مدد دپاره راغلو او په دېو باندې يې حمله وکړه او وې وژلو. بيا د داؤد سړو د داؤد نه لوظ واخستلو چې هغه به بيا هيڅکله د هغوئ سره جنګ له نۀ ځى. هغوئ ووئيل، ”تۀ د بنى اِسرائيلو دپاره لکه د رڼا اُميد يې او مونږ دا رڼا ختمېدل نۀ غواړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8081, '2 Samuel 21:18', '2 Samuel', 21, 18, '&nbsp;د دې نه پس په جوب کښې د فلستيانو سره يو بل جنګ وشو، چې په هغې کښې د حوسى قبيلې سِبکى يو دېو ووژلو چې د هغه دېو نوم سف وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8082, '2 Samuel 21:19', '2 Samuel', 21, 19, '&nbsp;د فلستيانو سره يو بل جنګ په جوب کښې وشو او د بيت‌لحم د يائير زوئ اِلحنان د جات جوليت ووژلو چې د هغۀ نېزه د کوټې د ستنې په شان غټه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8083, '2 Samuel 21:20', '2 Samuel', 21, 20, '&nbsp;بيا په جات کښې يو بل جنګ وشو چې په کښې يو دېو وو چې د هغۀ د هر لاس او د هرې پښې شپږ شپږ ګوتې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8084, '2 Samuel 21:21', '2 Samuel', 21, 21, '&nbsp;هغۀ په اِسرائيليانو پورې خندا وکړه او د داؤد ورور د سِمعه زوئ، يونتن هغه ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8085, '2 Samuel 21:22', '2 Samuel', 21, 22, '&nbsp;دا څلور د جات د دېوانو اولاد وو او داؤد او د هغۀ سړو دوئ وژلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8086, '2 Samuel 22:1', '2 Samuel', 22, 1, '&nbsp;کله چې مالِک خُدائ داؤد د ساؤل او خپلو نورو دشمنانو نه بچ کړو، نو داؤد د مالِک خُدائ په ثناء صِفت کښې دا وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8087, '2 Samuel 22:2', '2 Samuel', 22, 2, '&nbsp;”مالِک خُدائ زما ساتونکے دے، هغه زما د مضبوطې قلعې په شان دے، او هغه زما خلاصونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8088, '2 Samuel 22:3', '2 Samuel', 22, 3, '&nbsp;زما خُدائ پاک زما د حِفاظت ځائ دے. او د هغۀ سره په حِفاظت کښې يم. هغه ما د ډال په شان بچ کوى، هغه زما دِفاع کوى او بچ مې ساتى. هغه زما خلاصونکے دے، هغه زما ساتنه کوى او د زور ظلم نه مې بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8089, '2 Samuel 22:4', '2 Samuel', 22, 4, '&nbsp;زۀ مالِک خُدائ ته سوال کوم، او هغه مې د دشمنانو نه بچ کوى. د مالِک خُدائ ثناء صِفت دې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8090, '2 Samuel 22:5', '2 Samuel', 22, 5, '&nbsp;د مرګ ټولې چپې زما ګېرچاپېره وې، د تباهۍ سېلاب زۀ راګېر کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8091, '2 Samuel 22:6', '2 Samuel', 22, 6, '&nbsp;د مرګ خطره زما نه تاو وه، او قبر زما دپاره خپل دام خور کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8092, '2 Samuel 22:7', '2 Samuel', 22, 7, '&nbsp;په تکليف کښې ما مالِک خُدائ ته چغه کړه، ما خُدائ پاک ته د مدد دپاره سوال وکړو. د هغۀ د کور نه هغۀ زما آواز واورېدو. د مدد دپاره هغۀ زما فرياد واورېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8093, '2 Samuel 22:8', '2 Samuel', 22, 8, '&nbsp;بيا زمکه ولړزېده او وخوځېده، د آسمان بنيادونه وخوځېدل او ودرزېدل ځکه چې خُدائ پاک غصه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8094, '2 Samuel 22:9', '2 Samuel', 22, 9, '&nbsp;د هغۀ د سپېږمو نه لوګے راووتلو، او يوه تباه کوونکې لمبه او بل سکارۀ د هغۀ د خولې نه راووتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8095, '2 Samuel 22:10', '2 Samuel', 22, 10, '&nbsp;هغۀ آسمان وشلولو او لاندې راغلو، د هغۀ د پښو لاندې يوه توره تيارۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8096, '2 Samuel 22:11', '2 Samuel', 22, 11, '&nbsp;هغه د وزرو والا په خپل مخلوق باندې تېز والوتلو، هغۀ د هوا په وزرو باندې سفر وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8097, '2 Samuel 22:12', '2 Samuel', 22, 12, '&nbsp;هغۀ خپل ځان په تيارۀ کښې پټ کړو، د اوبو نه ډکه تکه توره وريځ د هغۀ نه ګېرچاپېره تاو شوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8098, '2 Samuel 22:13', '2 Samuel', 22, 13, '&nbsp;د هغۀ په وړاندې د برېښنا نه بلو سکارو لمبه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8099, '2 Samuel 22:14', '2 Samuel', 22, 14, '&nbsp;بيا مالِک خُدائ د تندر په شان شو، او د خُدائ تعالىٰ آواز واورېدے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8100, '2 Samuel 22:15', '2 Samuel', 22, 15, '&nbsp;هغۀ خپل غشى وويشتل او دشمنان يې خوارۀ وارۀ کړل، د برېښنا د پړق سره يې هغوئ وزغلول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');